    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        # Create a graph using adjacency list representation
        graph = [[] for _ in range(numCourses)]
        visited = [0 for _ in range(numCourses)]

        # Build the graph
        for x, y in prerequisites:
            graph[x].append(y)

        # Define a helper function for DFS
        def dfs(i):
            # If the course is marked as visiting, it means a cycle is detected
            if visited[i] == -1:
                return False
            # If the course is marked as visited, it means it's already been checked
            if visited[i] == 1:
                return True
            # Mark the course as visiting
            visited[i] = -1
            # Check all the prerequisites of the course
            for j in graph[i]:
                if not dfs(j):
                    return False
            # Mark the course as visited
            visited[i] = 1
            return True

        # Check all the courses
        for i in range(numCourses):
            if not dfs(i):
                return False
        return True

