class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        def get_position(square):
            row = (square - 1) // n
            col = (square - 1) % n
            if row % 2 == 1:
                col = n - 1 - col
            return n - 1 - row, col

        queue = [(1, 0)]
        visited = set([1])
        while queue:
            square, moves = queue.pop(0)
            if square == n * n:
                return moves
            for i in range(1, 7):
                next_square = square + i
                if next_square > n * n:
                    continue
                row, col = get_position(next_square)
                if board[row][col] != -1:
                    next_square = board[row][col]
                if next_square not in visited:
                    visited.add(next_square)
                    queue.append((next_square, moves + 1))
        return -1

