class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        from collections import deque
        # Initialize the result list and the deque
        result = []
        dq = deque()

        # Iterate over the list
        for i in range(len(nums)):
            # Remove elements from the back of the deque that are out of the window
            while dq and dq[0] < i - k + 1:
                dq.popleft()

            # Remove elements from the front of the deque that are smaller than the current element
            while dq and nums[dq[-1]] < nums[i]:
                dq.pop()

            # Add the current element to the deque
            dq.append(i)

            # Add the maximum element of the window to the result list
            if i >= k - 1:
                result.append(nums[dq[0]])

        return result

