    def reverseKGroup(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        dummy = ListNode(0)
        dummy.next = head
        pre = dummy
        while True:
            count = 0
            temp = pre
            while temp.next and count < k:
                temp = temp.next
                count += 1
            if count == k:
                cur = pre.next
                for _ in range(k - 1):
