            graph[v].append((u, c))

        # Function to find the minimum spanning tree using Kruskal's algorithm
        def kruskal():
            parent = list(range(n + 1))
            rank = [0] * (n + 1)
            edges = []
            for u in range(1, n + 1):
                for v, c in graph[u]:
                    edges.append((c, u, v))
            edges.sort()
            mst = []
            for c, u, v in edges:
                if find(u) != find(v):
                    union(u, v)
                    mst.append((u, v, c))
            return mst

        # Function to find the parent of a node
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        # Function to union two nodes
        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            elif rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

        # Find the minimum spanning tree
        mst = kruskal()

        # Create a new graph with the minimum spanning tree edges
        new_graph = [[] for _ in range(n + 1)]
        for u, v, c in mst:
            new_graph[u].append((v, c))
            new_graph[v].append((u, c))

