            distance[1] = 0
            queue = [(0, 1)]
            while queue:
                d, u = min(queue)
                queue.remove((d, u))
                for v, c in new_graph[u]:
                    if distance[u] + c < distance[v]:
                        distance[v] = distance[u] + c
                        queue.append((distance[v], v))
            return distance[1:]

        # Find the shortest distance from the king's residence to each settlement
        return dijkstra()

