    def max_city_score(self, n: int, m: int, scores: List[int], roads: List[Tuple[int, int]], start: int) -> int:
        # Create an adjacency list to represent the graph
        graph = [[] for _ in range(n + 1)]
        for u, v in roads:
            graph[u].append(v)
            graph[v].append(u)

        # Initialize variables to keep track of the maximum score and the previous city
        max_score = [0] * (n + 1)
        prev_city = [0] * (n + 1)

        # Perform DFS to find the maximum score
        def dfs(city, parent):
            if max_score[city] != 0:
                return max_score[city]
            max_score[city] = scores[city - 1]
            for neighbor in graph[city]:
                if neighbor != parent:
                    score = dfs(neighbor, city) + scores[city - 1]
                    if score > max_score[city]:
                        max_score[city] = score
                        prev_city[city] = neighbor
            return max_score[city]

        # Start DFS from the starting city
        dfs(start, 0)

        # Return the maximum score
        return max_score[start]

